def choose_move(observation):
    # Defensive defaults
    x = observation.get('player_x', 0)
    y = observation.get('player_y', 0)

    # Try to find goals in a generic, robust way across modes
    # Look for common keys that might indicate resources, enemies, or territory markers
    targets = []
    for key in ('resource_positions', 'resources', 'targets', 'item_positions', 'collect_positions'):
        pos = observation.get(key)
        if isinstance(pos, (list, tuple)):
            targets.extend(pos)
        elif isinstance(pos, dict):
            # unwrap if dict of positions
            for v in pos.values():
                if isinstance(v, (list, tuple)):
                    targets.extend(v)

    # Normalize targets to a list of (tx, ty)
    normalized = []
    for t in targets:
        if isinstance(t, (list, tuple)) and len(t) >= 2:
            normalized.append((int(t[0]), int(t[1])))
        elif isinstance(t, dict):
            if 'x' in t and 'y' in t:
                normalized.append((int(t['x']), int(t['y'])))
            elif 'pos' in t and isinstance(t['pos'], (list, tuple)):
                normalized.append((int(t['pos'][0]), int(t['pos'][1])))

    # If there is an enemy or opponent position
    opp = observation.get('opponent_position')
    if isinstance(opp, (list, tuple)) and len(opp) >= 2:
        opp_pos = (int(opp[0]), int(opp[1]))
    else:
        opp_pos = None

    # If there is territory control hints
    own_base = observation.get('base_position')
    if isinstance(own_base, (list, tuple)) and len(own_base) >= 2:
        base_pos = (int(own_base[0]), int(own_base[1]))
    else:
        base_pos = None

    # Decision heuristics: try to move toward closest relevant target if available,
    # otherwise move towards center-ish area to stay safe and flexible.
    best = None
    best_dist = None

    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    for t in normalized:
        d = dist((x, y), t)
        if best_dist is None or d < best_dist:
            best_dist = d
            best = t

    if best is not None:
        dx = best[0] - x
        dy = best[1] - y
        # Normalize to -1,0,1
        if dx != 0:
            dx = int(dx/abs(dx))
        else:
            dx = 0
        if dy != 0:
            dy = int(dy/abs(dy))
        else:
            dy = 0
        # Clip to allowed set just in case
        if dx not in (-1, 0, 1): dx = 0
        if dy not in (-1, 0, 1): dy = 0
        return [dx, dy]

    # Fallback: patrol toward center of map if dimensions known
    width = observation.get('map_width', 0)
    height = observation.get('map_height', 0)
    cx = width // 2 if width else x
    cy = height // 2 if height else y

    dx = cx - x
    dy = cy - y
    if dx != 0:
        dx = int(dx/abs(dx))
    else:
        dx = 0
    if dy != 0:
        dy = int(dy/abs(dy))
    else:
        dy = 0

    return [dx, dy]

